from datetime import date


class Loyalty:
    def __init__(self) -> None:
        # customer -> list of (day, points) earnings
        self._earnings = {}
        # customer -> list of (day, points) redemptions
        self._redemptions = {}

    def purchase(self, customer: str, amount: float, day: date) -> int:
        """Record a purchase; returns the number of points earned."""
        if amount <= 0:
            raise ValueError("Purchase amount must be greater than zero")
        points = int(amount // 10)
        self._earnings.setdefault(customer, []).append((day, points))
        return points

    def balance(self, customer: str, day: date) -> int:
        """Points the customer can spend on the given day."""
        earned = sum(p for d, p in self._earnings.get(customer, []) if d <= day)
        spent = sum(p for d, p in self._redemptions.get(customer, []) if d <= day)
        return earned - spent

    def redeem(self, customer: str, points: int, day: date) -> None:
        if points % 100 != 0:
            raise ValueError("Points can only be redeemed in multiples of 100")
        if points <= 0:
            raise ValueError("Points to redeem must be positive")
        if self.balance(customer, day) < points:
            raise ValueError("Insufficient points balance")
        self._redemptions.setdefault(customer, []).append((day, points))
